SELECT dc.id, dc.name, dc.country_code, dc.timezone,dc.zip_code, dc.latitude,dc.longitude, dc.parent_id,dc.level,dc.type, dc.index,dc.disabled, dc.kingdee_code,dc.code FROM dict_city dc LEFT JOIN dict_country cou ON dc.country_code=cou.id and cou.is_deleted=false WHERE dc.is_deleted=FALSE
AND dc.id in
#{item}

SELECT dc.id, dc.kingdee_code AS kingdeeCode, dc.name AS name, c.name_cn AS parentName, dc.update_time AS updateTime, dc.update_user_name AS updateUserName FROM dict_city dc LEFT JOIN dict_country c ON dc.country_code = c.id AND c.is_deleted = FALSE WHERE dc.is_deleted = FALSE AND dc.parent_id='0' AND
${params.sqlMap.default}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
dc.create_time desc

